effect.shader:
#define EPS 0.00001
#define PI 3.14159265359
float lum(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}
float getGradient(vec2 uv) {
    float gm = float(gradientMode);
    vec2 center = vec2(gradCenterX, gradCenterY);
    vec2 p = uv - center;
    p.x *= gradAspect;
    float g = 0.0;
    if (gm < 1.5) {
        float ang = gradAngle * PI / 180.0;
        vec2 dir = vec2(cos(ang), sin(ang));
        g = dot(p, dir) / max(gradScale, EPS) + 0.5;
    } else if (gm < 2.5) {
        float dist = length(p);
        g = dist / max(gradScale * 0.5, EPS);
    } else if (gm < 3.5) {
        float dist = length(p);
        float ang = gradAngle * PI / 180.0;
        float cs = cos(ang);
        float sn = sin(ang);
        vec2 rp = vec2(p.x * cs + p.y * sn, -p.x * sn + p.y * cs);
        rp.y *= 0.6;
        dist = length(rp);
        g = dist / max(gradScale * 0.5, EPS);
    } else if (gm < 4.5) {
        float ang = gradAngle * PI / 180.0;
        float cs = cos(ang);
        float sn = sin(ang);
        vec2 rp = vec2(p.x * cs + p.y * sn, -p.x * sn + p.y * cs);
        float dist = abs(rp.x) + abs(rp.y);
        g = dist / max(gradScale * 0.5, EPS);
    } else {
        float ang = atan(p.y, p.x + EPS);
        float targetAng = gradAngle * PI / 180.0;
        float diff = ang - targetAng;
        diff = mod(diff + PI, 2.0 * PI) - PI;
        g = abs(diff) / PI;
    }
    g += gradOffset;
    float soft = max(gradSoftness, 0.01);
    g = smoothstep(0.5 - soft, 0.5 + soft, g);
    if (gradInvert) {
        g = 1.0 - g;
    }
    return clamp(g, 0.0, 1.0);
}
vec3 gradeZone(vec3 rgb, float exposure, float contrast, float saturation,
               float gamma, float highlights, float shadows,
               vec3 tintCol, float tintStr, float temp) {
    vec3 result = rgb;
    if (abs(exposure) > EPS) {
        result *= pow(2.0, exposure);
    }
    if (abs(contrast) > 0.5) {
        float c = contrast / 100.0;
        float factor = 1.0 + c;
        result = (result - 0.18) * factor + 0.18;
        if (c > 0.0) {
            float s = c * 0.3;
            result = result + s * (result - 0.5) * (1.0 - abs(result - 0.5) * 2.0);
        }
    }
    if (abs(highlights) > 0.5 || abs(shadows) > 0.5) {
        float l = lum(result);
        float hlMask = smoothstep(0.5, 1.0, l);
        hlMask *= hlMask;
        float shMask = 1.0 - smoothstep(0.0, 0.5, l);
        shMask *= shMask;
        float hlAdj = highlights / 100.0 * 0.4;
        float shAdj = shadows / 100.0 * 0.4;
        float origLum = max(l, EPS);
        float newLum = l + hlAdj * hlMask + shAdj * shMask;
        result *= max(newLum, 0.0) / origLum;
    }
    if (abs(gamma - 1.0) > EPS) {
        result = pow(max(result, 0.0), vec3(1.0 / max(gamma, EPS)));
    }
    if (abs(saturation) > 0.5) {
        float s = 1.0 + saturation / 100.0;
        float l = lum(result);
        result = mix(vec3(l), result, s);
    }
    if (abs(temp) > 0.5) {
        float t = temp / 100.0 * 0.08;
        result.r += t;
        result.b -= t;
        result.g += t * 0.15;
    }
    if (tintStr > EPS) {
        result = mix(result, result * tintCol, tintStr);
    }
    return result;
}
void main() {
    vec2 uv = acScreenNorm;
    vec4 original = texture2DCv(inputImg.texture, uv);
    vec3 rgb = max(original.rgb, 0.0);
    vec3 baseRGB = rgb;
    float grad = getGradient(uv);
    if (viewGradient) {
        gl_FragColor = vec4(vec3(grad), 1.0);
        return;
    }
    vec3 brightGraded = gradeZone(rgb,
        brightExposure, brightContrast, brightSaturation,
        brightGamma, brightHighlights, brightShadows,
        brightTint.rgb, brightTintStr, brightTemp);
    vec3 darkGraded = gradeZone(rgb,
        darkExposure, darkContrast, darkSaturation,
        darkGamma, darkHighlights, darkShadows,
        darkTint.rgb, darkTintStr, darkTemp);
    vec3 result = mix(darkGraded, brightGraded, grad);
    if (abs(masterExposure) > EPS) {
        result *= pow(2.0, masterExposure);
    }
    if (abs(masterContrast) > 0.5) {
        float mc = masterContrast / 100.0;
        result = (result - 0.18) * (1.0 + mc) + 0.18;
    }
    if (abs(masterSaturation - 100.0) > 0.5) {
        float ms = masterSaturation / 100.0;
        float l = lum(result);
        result = mix(vec3(l), result, ms);
    }
    result = mix(baseRGB, result, globalMix);
    result = clamp(result, 0.0, 1.0);
    gl_FragColor = vec4(result, original.a);
}
